#!/usr/bin/env python3
from pathlib import Path
p=Path('public/dashboard.html')
if not p.exists():raise SystemExit('Dashboard not found; no changes made.')
s=p.read_text(encoding='utf-8')
old="function zelimuLCFilter(){\n const cl=$('lcClass'),q=$('lcSearch'),sel=$('lcLearner'),msg=$('lcSearchStatus');\n const classes=Array.isArray(state.classes)?state.classes:[],learners=Array.isArray(state.learners)?state.learners:[];\n const previousClass=cl.value,previousLearner=sel.value;\n const names=new Map(classes.filter(c=>c.id).map(c=>[String(c.id),[c.name||c.class_name||c.level_name||'Class',c.stream||''].filter(Boolean).join(' ')]));\n learners.forEach(l=>{if(l.class_id&&!names.has(String(l.class_id)))names.set(String(l.class_id),l.class_name||'Class');});\n cl.replaceChildren(new Option('Select grade / class',''),...[...names].sort((a,b)=>a[1].localeCompare(b[1],undefined,{numeric:true})).map(([id,name])=>new Option(name,id)));\n if(names.has(previousClass))cl.value=previousClass;\n q.disabled=!cl.value;sel.disabled=!cl.value;\n if(!cl.value){sel.replaceChildren(new Option('Select class first',''));msg.textContent='Select a class first.';return;}\n const term=q.value.trim().toLowerCase();\n const matches=learners.filter(l=>String(l.class_id||'')===cl.value).filter(l=>!term||[l.first_name,l.middle_name,l.last_name,l.admission_no,l.assessment_no].some(v=>String(v||'').toLowerCase().includes(term)));\n sel.replaceChildren(new Option('Select learner',''),...matches.slice(0,100).map(l=>new Option([l.first_name,l.middle_name,l.last_name].filter(Boolean).join(' ')+' ('+(l.admission_no||'—')+')',l.id)));\n if(matches.some(l=>String(l.id)===previousLearner))sel.value=previousLearner;\n msg.textContent=matches.length>100?matches.length+' matches; type more to narrow results.':matches.length+' learner(s) found.';\n}\n$('lcClass')?.addEventListener('change',()=>{$('lcSearch').value='';zelimuLCFilter();});\n$('lcSearch')?.addEventListener('input',zelimuLCFilter);\n"
new="function zelimuLCFilter(){\n const cl=$('lcClass'),q=$('lcSearch'),sel=$('lcLearner'),msg=$('lcSearchStatus');\n if(!cl||!q||!sel||!msg)return;\n const classes=Array.isArray(state.classes)?state.classes:[];\n const learners=Array.isArray(state.learners)?state.learners:[];\n const classKey=l=>String(l.enrollment_class_id||l.class_id||'');\n const selected=cl.value;\n const classNames=new Map(classes.filter(c=>c.id).map(c=>[String(c.id),[c.name||c.class_name||c.level_name||'Class',c.stream||''].filter(Boolean).join(' ')]));\n learners.forEach(l=>{const k=classKey(l);if(k&&!classNames.has(k))classNames.set(k,l.class_name||'Class');});\n const signature=[...classNames].map(([id,name])=>id+':'+name).join('|');\n if(cl.dataset.classSignature!==signature){\n   cl.replaceChildren(new Option('Select grade / class',''),...[...classNames].sort((a,b)=>a[1].localeCompare(b[1],undefined,{numeric:true})).map(([id,name])=>new Option(name,id)));\n   cl.dataset.classSignature=signature;\n   if(classNames.has(selected))cl.value=selected;\n }\n q.disabled=!cl.value;sel.disabled=!cl.value;\n if(!cl.value){sel.replaceChildren(new Option('Select class first',''));msg.textContent=classNames.size?'Select a class first.':'No configured classes loaded. Refresh school data.';return;}\n const term=q.value.trim().toLocaleLowerCase();\n const matched=learners.filter(l=>classKey(l)===cl.value).filter(l=>!term||[l.first_name,l.middle_name,l.last_name,l.admission_no,l.assessment_no].some(v=>String(v||'').toLocaleLowerCase().includes(term)));\n const previous=sel.value;\n sel.replaceChildren(new Option('Select learner',''),...matched.slice(0,100).map(l=>new Option([l.first_name,l.middle_name,l.last_name].filter(Boolean).join(' ')+' ('+(l.admission_no||'—')+')',l.id)));\n if(matched.some(l=>String(l.id)===previous))sel.value=previous;\n if(!matched.length){\n   const unassigned=learners.filter(l=>!classKey(l)).length;\n   msg.textContent=unassigned?`No learners matched this class. ${unassigned} learner(s) have no class assignment in the loaded records; check enrollment records.`:'No learners matched this class or search.';\n }else msg.textContent=matched.length>100?`${matched.length} matches; type a name or admission number to narrow results.`:`${matched.length} learner(s) found.`;\n}\n$('lcClass')?.addEventListener('change',()=>{$('lcSearch').value='';zelimuLCFilter();});\nlet zelimuLCSearchTimer;\n$('lcSearch')?.addEventListener('input',()=>{clearTimeout(zelimuLCSearchTimer);zelimuLCSearchTimer=setTimeout(zelimuLCFilter,160);});\n"
if new in s:print('Already installed.');raise SystemExit(0)
if s.count(old)!=1:raise SystemExit('Expected certificate search code differs; no changes made.')
p.write_text(s.replace(old,new,1),encoding='utf-8')
print('Repaired certificate dropdown rebuild, search debounce and missing-class diagnostics.')
